<?php
/* Independent BKR broker directory + WhatsApp campaigns. CRUD touches bkr_list only. */
mysqli_report(MYSQLI_REPORT_OFF);
$con = @mysqli_connect('localhost', 'root', '', 'tdl');
if (!$con) { http_response_code(500); die('Database connection failed. Please check the database connection settings.'); }
mysqli_set_charset($con, 'utf8mb4');
function h($v) { return htmlspecialchars((string)($v ?? ''), ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
$fields = ['name','number1','number2','area_working','description','grade','person_description','contacted_from','serious','status'];
$statusOptions = ['New','Open','Follow-up','Hold','Contacted','Interested','Inactive','Closed'];
if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_GET['bkr_action'])) {
    header('Content-Type: application/json; charset=utf-8');
    $action = (string)$_GET['bkr_action'];
    $id = filter_input(INPUT_POST, 'id', FILTER_VALIDATE_INT);
    if ($action === 'delete') {
        if (!$id) { http_response_code(400); echo json_encode(['ok'=>false,'error'=>'Invalid broker ID.']); exit; }
        $stmt = mysqli_prepare($con, 'DELETE FROM bkr_list WHERE id = ?');
        if (!$stmt) { http_response_code(500); echo json_encode(['ok'=>false,'error'=>'Could not prepare delete.']); exit; }
        mysqli_stmt_bind_param($stmt, 'i', $id); $ok = mysqli_stmt_execute($stmt); $affected = mysqli_stmt_affected_rows($stmt); mysqli_stmt_close($stmt);
        if (!$ok || !$affected) { http_response_code(400); echo json_encode(['ok'=>false,'error'=>'Broker was not deleted. It may already have been removed.']); exit; }
        echo json_encode(['ok'=>true,'message'=>'Broker deleted.']); exit;
    }
    if (!in_array($action, ['create','update'], true)) { http_response_code(400); echo json_encode(['ok'=>false,'error'=>'Unsupported action.']); exit; }
    $v = [];
    foreach (array_slice($fields, 0, 8) as $field) $v[$field] = trim((string)($_POST[$field] ?? ''));
    $v['serious'] = isset($_POST['serious']) && (string)$_POST['serious'] === '1' ? '1' : '0';
    $v['status'] = trim((string)($_POST['status'] ?? 'New'));
    if (!in_array($v['status'], $statusOptions, true)) $v['status'] = 'New';
    if ($v['name'] === '') { http_response_code(422); echo json_encode(['ok'=>false,'error'=>'Broker name is required.']); exit; }
    if ($action === 'create') {
        $stmt = mysqli_prepare($con, 'INSERT INTO bkr_list (name, number1, number2, area_working, description, grade, person_description, contacted_from, serious, status) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)');
        if ($stmt) mysqli_stmt_bind_param($stmt, 'ssssssssss', $v['name'], $v['number1'], $v['number2'], $v['area_working'], $v['description'], $v['grade'], $v['person_description'], $v['contacted_from'], $v['serious'], $v['status']);
    } else {
        if (!$id) { http_response_code(400); echo json_encode(['ok'=>false,'error'=>'Invalid broker ID.']); exit; }
        $stmt = mysqli_prepare($con, 'UPDATE bkr_list SET name=?, number1=?, number2=?, area_working=?, description=?, grade=?, person_description=?, contacted_from=?, serious=?, status=? WHERE id=?');
        if ($stmt) mysqli_stmt_bind_param($stmt, 'ssssssssssi', $v['name'], $v['number1'], $v['number2'], $v['area_working'], $v['description'], $v['grade'], $v['person_description'], $v['contacted_from'], $v['serious'], $v['status'], $id);
    }
    if (!$stmt) { http_response_code(500); echo json_encode(['ok'=>false,'error'=>'Database query could not be prepared. Check that bkr_list has the expected columns.']); exit; }
    $ok = mysqli_stmt_execute($stmt); $err = mysqli_stmt_error($stmt); mysqli_stmt_close($stmt);
    if (!$ok) { http_response_code(500); echo json_encode(['ok'=>false,'error'=>'Save failed: '.$err]); exit; }
    echo json_encode(['ok'=>true,'message'=>$action==='create'?'Broker added successfully.':'Broker updated successfully.']); exit;
}
$sql = "SELECT `id`, `name`, `number1`, `number2`, `area_working`, `description`, `grade`, `person_description`, `contacted_from`, `serious`, `status` FROM `bkr_list` ORDER BY `name` ASC, `id` ASC";
$result = mysqli_query($con, $sql);
if (!$result) { http_response_code(500); die('Could not load bkr_list: ' . h(mysqli_error($con))); }
$brokers = [];
while ($r = mysqli_fetch_assoc($result)) { $brokers[] = $r; }
mysqli_free_result($result);
mysqli_close($con);
$payload = json_encode($brokers, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_HEX_TAG | JSON_HEX_APOS | JSON_HEX_QUOT | JSON_HEX_AMP);
?>
