<script>
'use strict';
const BROKERS = <?= $payload ?: '[]' ?>;
const STORAGE_KEY = 'tdl_bkr_whatsapp_campaigns_v1';
const $ = id => document.getElementById(id);
let selectedIds = new Set();
let campaigns = loadCampaigns();
let activeId = '';
let currentWhatsAppUrl = '';
let lastVisible = [];
function esc(v){return String(v == null ? '' : v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function cleanPhone(v){return String(v||'').replace(/\D/g,'');}
function usablePhone(b){let raw=cleanPhone(b.number1)||cleanPhone(b.number2);if(raw.length===10)raw='91'+raw;return raw;}
function norm(v){return String(v==null?'':v).toLocaleLowerCase().trim();}
function uniqueVals(key){return [...new Set(BROKERS.map(b=>String(b[key]??'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b));}
function fillSelect(id,vals,label){const el=$(id);const old=el.value;el.innerHTML='<option value="">'+label+'</option>'+vals.map(v=>'<option value="'+esc(v)+'">'+esc(v)+'</option>').join('');if(vals.includes(old))el.value=old;}
function initFilters(){fillSelect('areaFilter',uniqueVals('area_working'),'All areas');fillSelect('gradeFilter',uniqueVals('grade'),'All grades');fillSelect('contactedFilter',uniqueVals('contacted_from'),'All sources');fillSelect('statusFilter',[...new Set([...['New','Open','Follow-up','Hold','Contacted','Interested','Inactive','Closed'],...uniqueVals('status')])],'All statuses');}
function matches(b){const q=norm($('search').value);const hay=[b.name,b.number1,b.number2,b.area_working,b.description,b.grade,b.person_description,b.contacted_from,b.status].map(norm).join(' ');return (!q||hay.includes(q))&&(!$('areaFilter').value||String(b.area_working||'').trim()===$('areaFilter').value)&&(!$('gradeFilter').value||String(b.grade||'').trim()===$('gradeFilter').value)&&(!$('seriousFilter').value||String(Number(b.serious)===1?'1':'0')===$('seriousFilter').value)&&(!$('contactedFilter').value||String(b.contacted_from||'').trim()===$('contactedFilter').value)&&(!$('statusFilter').value||String(b.status||'New').trim()===$('statusFilter').value);}
function phoneCell(b,key){const n=String(b[key]||'').trim();if(!n)return '<span class="muted">—</span>';return '<a class="number-link" target="_blank" rel="noopener noreferrer" href="https://wa.me/'+esc(cleanPhone(n).length===10?'91'+cleanPhone(n):cleanPhone(n))+'">'+esc(n)+'</a>';}
function renderRows(){lastVisible=BROKERS.filter(matches);$('statTotal').textContent=BROKERS.length;$('statFiltered').textContent=lastVisible.length;$('statSelected').textContent=selectedIds.size;$('selectionLabel').textContent=selectedIds.size+' selected';$('emptyRows').hidden=lastVisible.length>0;$('brokerRows').innerHTML=lastVisible.map(b=>{const id=String(b.id);const grade=String(b.grade||'').trim();return '<tr><td><input class="check row-check" type="checkbox" data-id="'+esc(id)+'" '+(selectedIds.has(id)?'checked':'')+' aria-label="Select '+esc(b.name)+'"></td><td><div class="name">'+esc(b.name||'Unnamed broker')+'</div><div class="muted">ID '+esc(id)+'</div></td><td>'+phoneCell(b,'number1')+'</td><td>'+phoneCell(b,'number2')+'</td><td class="area-cell">'+esc(b.area_working||'—')+'</td><td><span class="grade" data-grade="'+esc(grade)+'">'+esc(grade||'—')+'</span></td><td><span class="broker-status">'+esc(b.status||'New')+'</span></td><td class="'+(Number(b.serious)===1?'serious':'not-serious')+'">'+(Number(b.serious)===1?'● Serious':'—')+'</td><td>'+esc(b.contacted_from||'—')+'</td><td><div>'+esc(b.description||'')+'</div><div class="muted">'+esc(b.person_description||'')+'</div></td><td><div class="actions"><button class="btn-light btn-small" data-edit-broker="'+esc(id)+'" type="button">Edit</button><button class="btn-red btn-small" data-delete-broker="'+esc(id)+'" type="button">Delete</button></div></td></tr>';}).join('');const all=lastVisible.length>0&&lastVisible.every(b=>selectedIds.has(String(b.id)));$('selectAllBox').checked=all;$('selectAllBox').indeterminate=!all&&lastVisible.some(b=>selectedIds.has(String(b.id)));}
function loadCampaigns(){try{const a=JSON.parse(localStorage.getItem(STORAGE_KEY)||'[]');return Array.isArray(a)?a.filter(c=>c&&c.id&&Array.isArray(c.queue)):[];}catch(e){return [];}}
function persist(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(campaigns));}catch(e){alert('Could not save campaigns in this browser. Please check browser storage settings.');}renderCampaignList();updateCampaignUI();}
function active(){return campaigns.find(c=>c.id===activeId)||null;}
function makeId(){return 'bkr_'+Date.now()+'_'+Math.random().toString(36).slice(2,9);}
function selectedBrokers(){return BROKERS.filter(b=>selectedIds.has(String(b.id))&&usablePhone(b));}
function createCampaign(){const queue=selectedBrokers().map(b=>({id:String(b.id),name:String(b.name||''),number1:String(b.number1||''),number2:String(b.number2||''),area_working:String(b.area_working||''),description:String(b.description||''),grade:String(b.grade||''),person_description:String(b.person_description||''),contacted_from:String(b.contacted_from||''),serious:Number(b.serious)===1?1:0,status:String(b.status||'New')}));if(!queue.length){alert('Select at least one broker with a usable phone number.');return;}const name=prompt('Enter a name for this broker WhatsApp campaign:', 'BKR Campaign '+new Date().toLocaleDateString());if(name===null)return;if(!name.trim()){alert('Please enter a campaign name.');return;}const c={id:makeId(),name:name.trim(),queue,index:0,status:'running',message:$('campaignMessage').value||'',createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};campaigns.unshift(c);activeId=c.id;persist();renderCampaignList();openModal();}
function saveActive(){const c=active();if(!c)return;c.updatedAt=new Date().toISOString();c.message=$('campaignMessage').value;persist();}
function setStatus(status){const c=active();if(!c)return;c.status=status;c.updatedAt=new Date().toISOString();persist();}
function currentBroker(c=active()){return c&&c.queue[c.index]?c.queue[c.index]:null;}
function buildMessage(b,c){let m=String(c.message||'');const map={name:b.name,number1:b.number1,number2:b.number2,area:b.area_working,grade:b.grade,status:b.status,description:b.description,person_description:b.person_description,contacted_from:b.contacted_from};return m.replace(/\{\{\s*(name|number1|number2|area|grade|status|description|person_description|contacted_from)\s*\}\}/gi,(_,k)=>String(map[k.toLowerCase()]||''));}
function whatsappUrl(b,c){const phone=usablePhone(b);if(!phone)return '';const message=buildMessage(b,c);return 'https://wa.me/'+encodeURIComponent(phone)+(message.trim()?'?text='+encodeURIComponent(message):'');}
function openCurrent(){const c=active();const b=currentBroker(c);if(!c||!b){alert('There is no current broker in this campaign.');return;}if(c.status!=='running'){alert('Resume this campaign before opening WhatsApp.');return;}const url=whatsappUrl(b,c);if(!url){alert('This broker has no usable phone number.');return;}window.open(url,'_blank','noopener,noreferrer');}
function advance(skip){const c=active();if(!c||c.status!=='running')return;if(c.index<c.queue.length)c.index++;if(c.index>=c.queue.length)c.status='completed';c.updatedAt=new Date().toISOString();persist();renderCampaignList();if($('campaignModal').classList.contains('open'))renderModal();}
function pause(){const c=active();if(!c||c.status!=='running')return;setStatus('paused');}
function resume(id){const c=campaigns.find(x=>x.id===id)||active();if(!c)return;if(c.status==='completed'){alert('This campaign is already completed.');return;}activeId=c.id;c.status='running';c.updatedAt=new Date().toISOString();$('campaignMessage').value=c.message||'';persist();openModal();}
function stop(){const c=active();if(!c)return;if(!confirm('Stop and remove campaign “'+c.name+'”? Other saved campaigns will remain available.'))return;campaigns=campaigns.filter(x=>x.id!==c.id);activeId='';persist();$('campaignModal').classList.remove('open');}
function renderCampaignList(){$('statCampaigns').textContent=campaigns.length;const host=$('campaignList');if(!campaigns.length){host.innerHTML='<div class="empty">No saved BKR campaigns yet.</div>';return;}host.innerHTML=campaigns.map(c=>'<div class="campaign-item '+(c.id===activeId?'active':'')+'"><div style="min-width:0"><strong>'+esc(c.name)+'</strong><div class="muted">'+Math.min(c.index,c.queue.length)+' / '+c.queue.length+' brokers · <span class="status">'+esc(c.status)+'</span></div></div><button class="'+(c.status==='paused'?'btn-primary':'btn-light')+' btn-small" data-resume="'+esc(c.id)+'">'+(c.status==='completed'?'View':'Resume / Open')+'</button></div>').join('');host.querySelectorAll('[data-resume]').forEach(btn=>btn.addEventListener('click',()=>{const c=campaigns.find(x=>x.id===btn.dataset.resume);if(c){activeId=c.id;$('campaignMessage').value=c.message||'';if(c.status==='completed'){persist();openModal();}else resume(c.id);}}));}
function renderCampaignUIContact(){const c=active();const b=currentBroker(c);const card=$('currentContact');if(!c){card.innerHTML='<div class="person">Ready for your campaign</div><div class="contact-details">Choose brokers and create a named campaign.</div>';return;}if(!b){card.innerHTML='<div class="person">Campaign '+(c.status==='completed'?'completed':'has no remaining brokers')+'</div><div class="contact-details">'+esc(c.name)+'</div>';return;}card.innerHTML='<div class="muted">'+esc(c.name)+' · BROKER '+(c.index+1)+' OF '+c.queue.length+'</div><div class="person">'+esc(b.name||'Unnamed broker')+'</div><div class="phone">'+esc(b.number1||b.number2||'No phone number')+'</div><div class="contact-details">Area: '+esc(b.area_working||'—')+'\nGrade: '+esc(b.grade||'—')+'\nStatus: '+esc(b.status||'New')+'\nSerious: '+(b.serious?'Yes':'No')+'\n'+esc(b.description||'')+'\n'+esc(b.person_description||'')+'</div>';}
function updateCampaignUI(){const c=active();$('activeCampaignPill').textContent=c?c.name:'No active campaign';const status=c?c.status:'idle';$('campaignStatus').textContent=c?(status.toUpperCase()+' · '+c.name):'Create a campaign using selected brokers, or resume a saved campaign.';$('progressFill').style.width=c&&c.queue.length?Math.round(Math.min(c.index,c.queue.length)/c.queue.length*100)+'%':'0%';$('progressText').textContent=c?Math.min(c.index,c.queue.length)+' of '+c.queue.length+' brokers advanced · '+status:'No campaign selected.';$('openWhatsApp').disabled=!c||status!=='running'||!currentBroker(c);$('nextContact').disabled=!c||status!=='running'||!currentBroker(c);$('skipContact').disabled=!c||status!=='running'||!currentBroker(c);$('pauseCampaign').disabled=!c||status!=='running';$('resumeCampaign').disabled=!c||status!=='paused';$('stopCampaign').disabled=!c;$('campaignMessage').disabled=!c;renderCampaignUIContact();if($('campaignModal').classList.contains('open'))renderModal();}
function openModal(){if(!active())return;$('campaignModal').classList.add('open');renderModal();}
function closeModal(){$('campaignModal').classList.remove('open');}
function renderModal(){const c=active();if(!c)return;$('modalTitle').textContent=c.name;$('modalSubtitle').textContent='Broker campaign · '+c.status;$('modalStatus').textContent=Math.min(c.index,c.queue.length)+' of '+c.queue.length+' brokers advanced';const b=currentBroker(c);if(!b){$('modalContact').innerHTML='<div class="person">'+(c.status==='completed'?'Campaign completed':'No current broker')+'</div><div class="contact-details">'+esc(c.name)+'</div>';}else{$('modalContact').innerHTML='<div class="muted">BROKER '+(c.index+1)+' OF '+c.queue.length+'</div><div class="person">'+esc(b.name||'Unnamed broker')+'</div><div class="phone">'+esc(b.number1||b.number2||'No phone number')+'</div><div class="contact-details">Area: '+esc(b.area_working||'—')+'\nGrade: '+esc(b.grade||'—')+'\nStatus: '+esc(b.status||'New')+'\nSerious: '+(b.serious?'Yes':'No')+'\n'+esc(b.description||'')+'\n'+esc(b.person_description||'')+'</div>';}$('modalOpenWhatsApp').disabled=!b||c.status!=='running';$('modalNext').disabled=!b||c.status!=='running';$('modalSkip').disabled=!b||c.status!=='running';$('modalPause').disabled=c.status!=='running';$('modalResume').disabled=c.status!=='paused';$('modalStop').disabled=!c;}
function openBrokerForm(b){const form=$('brokerForm');form.reset();$('brokerId').value=b?String(b.id):'';$('brokerModalTitle').textContent=b?'Edit broker':'Add broker';$('saveBroker').textContent=b?'Update broker':'Save broker';$('brokerFormStatus').textContent='';if(b){$('brokerName').value=b.name||'';$('brokerNumber1').value=b.number1||'';$('brokerNumber2').value=b.number2||'';$('brokerArea').value=b.area_working||'';$('brokerGrade').value=b.grade||'';$('brokerContactedFrom').value=b.contacted_from||'';$('brokerStatus').value=b.status||'New';$('brokerDescription').value=b.description||'';$('brokerPersonDescription').value=b.person_description||'';$('brokerSerious').checked=Number(b.serious)===1;}$('brokerModal').classList.add('open');$('brokerName').focus();}
function closeBrokerForm(){$('brokerModal').classList.remove('open');}
$('addBroker').addEventListener('click',()=>openBrokerForm(null));$('closeBrokerModal').addEventListener('click',closeBrokerForm);$('cancelBroker').addEventListener('click',closeBrokerForm);$('brokerModal').addEventListener('click',e=>{if(e.target===$('brokerModal'))closeBrokerForm();});
$('brokerRows').addEventListener('click',async e=>{const edit=e.target.closest('[data-edit-broker]');const del=e.target.closest('[data-delete-broker]');if(edit){const b=BROKERS.find(x=>String(x.id)===edit.dataset.editBroker);if(b)openBrokerForm(b);return;}if(del){const id=del.dataset.deleteBroker;const b=BROKERS.find(x=>String(x.id)===id);if(!b)return;if(!confirm('Permanently delete broker “'+(b.name||'Unnamed broker')+'” from bkr_list? This cannot be undone.'))return;del.disabled=true;try{const fd=new FormData();fd.append('id',id);const r=await fetch(location.pathname+'?bkr_action=delete',{method:'POST',body:fd});const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'Delete failed.');selectedIds.delete(id);alert(d.message);location.reload();}catch(err){alert(err.message||'Could not delete broker.');del.disabled=false;}}});
$('brokerForm').addEventListener('submit',async e=>{e.preventDefault();const button=$('saveBroker');button.disabled=true;$('brokerFormStatus').textContent='Saving…';try{const fd=new FormData(e.currentTarget);fd.set('serious',$('brokerSerious').checked?'1':'0');const action=$('brokerId').value?'update':'create';const r=await fetch(location.pathname+'?bkr_action='+action,{method:'POST',body:fd});const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'Could not save broker.');$('brokerFormStatus').textContent=d.message;location.reload();}catch(err){$('brokerFormStatus').textContent=err.message||'Could not save broker.';}finally{button.disabled=false;}});
$('search').addEventListener('input',renderRows);['areaFilter','gradeFilter','seriousFilter','contactedFilter','statusFilter'].forEach(id=>$(id).addEventListener('change',renderRows));$('resetFilters').addEventListener('click',()=>{$('search').value='';['areaFilter','gradeFilter','seriousFilter','contactedFilter','statusFilter'].forEach(id=>$(id).value='');renderRows();});
$('brokerRows').addEventListener('change',e=>{if(!e.target.classList.contains('row-check'))return;const id=e.target.dataset.id;if(e.target.checked)selectedIds.add(id);else selectedIds.delete(id);renderRows();});$('selectAllBox').addEventListener('change',()=>{lastVisible.forEach(b=>{if($('selectAllBox').checked)selectedIds.add(String(b.id));else selectedIds.delete(String(b.id));});renderRows();});$('selectVisible').addEventListener('click',()=>{lastVisible.forEach(b=>selectedIds.add(String(b.id)));renderRows();});$('clearSelection').addEventListener('click',()=>{selectedIds.clear();renderRows();});$('startCampaign').addEventListener('click',createCampaign);
$('openWhatsApp').addEventListener('click',openCurrent);$('nextContact').addEventListener('click',()=>advance(false));$('skipContact').addEventListener('click',()=>advance(true));$('pauseCampaign').addEventListener('click',pause);$('resumeCampaign').addEventListener('click',()=>{const c=active();if(c)resume(c.id);});$('stopCampaign').addEventListener('click',stop);$('refreshCampaigns').addEventListener('click',()=>{campaigns=loadCampaigns();renderCampaignList();updateCampaignUI();});
$('closeModal').addEventListener('click',closeModal);$('campaignModal').addEventListener('click',e=>{if(e.target===$('campaignModal'))closeModal();});$('modalOpenWhatsApp').addEventListener('click',openCurrent);$('modalNext').addEventListener('click',()=>advance(false));$('modalSkip').addEventListener('click',()=>advance(true));$('modalPause').addEventListener('click',pause);$('modalResume').addEventListener('click',()=>{const c=active();if(c)resume(c.id);});$('modalStop').addEventListener('click',stop);$('campaignMessage').addEventListener('input',()=>{const c=active();if(c){c.message=$('campaignMessage').value;c.updatedAt=new Date().toISOString();try{localStorage.setItem(STORAGE_KEY,JSON.stringify(campaigns));}catch(e){};}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();closeBrokerForm();}});
initFilters();renderRows();renderCampaignList();if(campaigns.length){const unfinished=campaigns.find(c=>c.status==='paused'||c.status==='running');if(unfinished){activeId=unfinished.id;$('campaignMessage').value=unfinished.message||'';}}updateCampaignUI();renderCampaignList();
</script></body></html>
